  expect(state.commands[driftCheck - 1]).toMatchObject({
    args: ["run", "@pantoken/docs#docs:api:en"],
    cwd: state.commands[driftCheck].cwd,
  });
  expect(state.commands.some((command) => command.args.join(" ") === "run check:publish")).toBe(
    true,
  );
});

