      state.commands
        .slice(0, index)
        .some(
          (command) =>
            command.executable === process.execPath &&
            JSON.stringify(command.args) === JSON.stringify(["docs/scripts/site-themes.ts"]) &&
            command.cwd === check.cwd,
        ),
    ).toBe(true);
  }
});

